# Refined content analysis to handle potential empty or incompatible files
def analyze_file_content_safe(file_path):
    try:
        with open(file_path, 'r', encoding='utf-8') as f:
            text = f.read()
        word_count = Counter(text.split())
        return {
            "file": file_path,
            "word_count": sum(word_count.values()),
            "most_common_words": word_count.most_common(10)
        }
    except Exception as e:
        return {"file": file_path, "word_count": 0, "most_common_words": [], "error": str(e)}

# Reanalyzing the files with safety checks
